const D = { scale: 1, density: .6, energy: .65, speed: 1, arms: .6, hue: 45, x: .5, y: .5, style: 'spectral-glow', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const HW = Math.max(140, Math.floor(width * 0.5)), HH = Math.max(140, Math.floor(height * 0.5));
const style = P.style;

// ground color per style
let bg;
if (style === 'blueprint') bg = [212, 82, 30];
else if (style === 'ink') bg = [38, 15, 86];
else if (style === 'gold') bg = [32, 48, 9];
else if (style === 'neon') bg = [265, 55, 6];
else bg = [230, 55, 10]; // spectral-glow deep indigo ground

// (re)build trail buffer on size or style change
if (!S.tb || S.tw !== HW || S.th !== HH) { S.tb = createGraphics(HW, HH); S.tb.colorMode(HSB,360,100,100,100); S.tw = HW; S.th = HH; S.style = null; }
if (S.style !== style) { S.tb.noStroke(); S.tb.fill(bg[0], bg[1], bg[2]); S.tb.rect(0,0,HW,HH); S.style = style; }

// cached ambient radial glow sprite (lifts mid-frame luminance; keeps default off the black floor)
if (!S.amb || S.ambStyle !== style) {
  S.ambStyle = style;
  const G = 128; if (!S.amb) { S.amb = createGraphics(G, G); S.amb.colorMode(HSB,360,100,100,100); }
  const ag = S.amb; ag.clear(); ag.noStroke();
  let ah, as;
  if (style === 'blueprint') { ah = 205; as = 65; }
  else if (style === 'gold') { ah = 40; as = 82; }
  else if (style === 'neon') { ah = 295; as = 70; }
  else { ah = 45; as = 62; }
  for (let r = G*0.5; r > 0; r -= 2) { const f = 1 - r/(G*0.5); ag.fill(ah, as*(1-f*0.55), 100, 3 + f*f*10); ag.ellipse(G/2, G/2, r*2); }
}

// seed-driven Fourier coefficients
const N = Math.round(4 + P.density * 10);
if (S.seedUsed !== P.seed || S.n !== N) {
  S.seedUsed = P.seed; S.n = N;
  const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7) * 43758.5453; return s - Math.floor(s); };
  S.fq = []; S.am = []; S.ph = [];
  for (let k = 0; k < N; k++) {
    const sign = fr(k*3+1) < 0.4 ? -1 : 1;
    S.fq.push(sign * (k === 0 ? 1 : Math.round(1 + fr(k*3+2) * 7)));
    S.am.push(1 / (1 + k * (0.45 + fr(k*3+3) * 1.0)));
    S.ph.push(fr(k*3+4) * 6.2831);
  }
  const amsum = S.am.reduce((a,b)=>a+b,0); S.am = S.am.map(a=>a/amsum);
  S.hoff = fr(99) * 60;
}

const tb = S.tb;
// gentle trail fade -> luminous decay (glow styles keep more; ink/blueprint clean up faster)
tb.push(); tb.noStroke();
const fade = (style === 'ink' || style === 'blueprint') ? 5 : 2.3;
tb.fill(bg[0], bg[1], bg[2], fade); tb.rect(0,0,HW,HH); tb.pop();

const t = K.t * (0.5 + P.speed * 0.9);
const drift = K.t * 0.02; // continuous coefficient drift -> the figure never exactly closes
const cx = HW*0.5, cy = HH*0.5;
const R = Math.min(HW,HH) * 0.46 * (0.4 + P.scale * 0.72);
const hb = (P.hue + S.hoff + K.section * 20) % 360;
function tip(tt) {
  let x = cx, y = cy;
  for (let k = 0; k < S.n; k++) {
    const f = S.fq[k] * (1 + 0.05 * Math.sin(drift*1.3 + k));
    const ang = f*tt + S.ph[k] + drift*(k+1)*0.35;
    x += R*S.am[k]*Math.cos(ang); y += R*S.am[k]*Math.sin(ang);
  }
  return [x,y];
}

// draw a short arc of the trace this frame (substeps -> smooth continuous luminous line)
const steps = 40;
const dt = 0.08 + P.speed * 0.05;
const eg = 0.5 + P.energy * 0.95 + A.rms * 0.5;
let prev = S.lastTip || tip(t);
const seg = [];
for (let s = 1; s <= steps; s++) seg.push(tip(t + (s/steps)*dt));
tb.noFill();
// pass 1: wide soft bloom (skip ink)
if (style !== 'ink') {
  tb.strokeWeight(5.5); let pp = prev;
  for (let s = 0; s < seg.length; s++) {
    const p = seg[s], tt = t + ((s+1)/steps)*dt;
    if (style === 'neon') tb.stroke((hb + tt*50)%360, 95, 100, 9*eg);
    else if (style === 'blueprint') tb.stroke(200, 28, 100, 6*eg);
    else if (style === 'gold') tb.stroke(38, 85, 100, 10*eg);
    else tb.stroke(44, 80, 100, 11*eg); // spectral-glow gold bloom
    tb.line(pp[0],pp[1],p[0],p[1]); pp = p;
  }
}
// pass 2: bright thin core
tb.strokeWeight(style === 'ink' ? 1.8 : 1.5); let pc = prev;
for (let s = 0; s < seg.length; s++) {
  const p = seg[s], tt = t + ((s+1)/steps)*dt;
  if (style === 'neon') tb.stroke((hb + tt*50)%360, 90, 100, 95);
  else if (style === 'ink') tb.stroke(30, 62, 20, 85);
  else if (style === 'blueprint') tb.stroke(0, 0, 100, 92);
  else if (style === 'gold') tb.stroke(45, 72, 100, 95);
  else tb.stroke(48, 58, 100, 95); // spectral-glow bright gold core
  tb.line(pc[0],pc[1],p[0],p[1]); pc = p;
}
S.lastTip = seg[seg.length-1];

// composite the trail
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(tb, 0, 0, width, height);
pop();

// ambient center glow lifts luminance (glow styles; ink/blueprint grounds already bright)
if (style !== 'ink' && style !== 'blueprint') {
  push(); blendMode(ADD);
  const gA = (0.55 + P.energy*0.55) * (0.75 + K.swell*0.25);
  const gs = u * (1.5 + 0.18*Math.sin(K.t*0.2));
  tint(0, 0, 100, 42*gA + A.rms*28);
  image(S.amb, width*0.5 - gs/2, height*0.5 - gs/2, gs, gs);
  blendMode(BLEND); pop();
}

// live rotating epicycle chain (circles + radii) on top -> the Fourier construction, unmistakable
if (P.arms > 0.04) {
  push(); translate(width*0.5, height*0.5);
  const AR = Math.min(width,height) * 0.46 * (0.4 + P.scale * 0.72);
  let x = 0, y = 0;
  const aA = (style === 'blueprint' ? 72 : 46) * P.arms;
  for (let k = 0; k < S.n; k++) {
    const f = S.fq[k] * (1 + 0.05 * Math.sin(drift*1.3 + k));
    const ang = f*t + S.ph[k] + drift*(k+1)*0.35;
    const rad = AR * S.am[k];
    const nx = x + rad*Math.cos(ang), ny = y + rad*Math.sin(ang);
    let ch, cs, cb;
    if (style === 'blueprint') { ch = 200; cs = 38; cb = 100; }
    else if (style === 'ink') { ch = 30; cs = 45; cb = 24; }
    else if (style === 'gold') { ch = (38 + k*3) % 360; cs = 72; cb = 100; }
    else if (style === 'neon') { ch = (hb + k/S.n*300) % 360; cs = 92; cb = 100; }
    else { ch = (hb + k/S.n*300 + K.t*8) % 360; cs = 85; cb = 100; } // spectral-glow full spectrum
    noFill();
    stroke(ch, cs*0.9, cb, aA*0.5); strokeWeight(1.1); ellipse(x, y, rad*2);
    stroke(ch, cs, cb, aA); strokeWeight(1.4); line(x, y, nx, ny);
    noStroke(); fill(ch, cs*0.75, cb, aA*1.2); ellipse(nx, ny, 3);
    x = nx; y = ny;
  }
  // bright drawing head
  const head = 4 + A.treble*10 + K.pulse*4;
  const hh = style === 'ink' ? 30 : (style === 'blueprint' ? 200 : 48);
  const hs = style === 'ink' ? 62 : (style === 'blueprint' ? 30 : 70);
  const hbb = style === 'ink' ? 26 : 100;
  noStroke();
  drawingContext.shadowBlur = (style === 'ink' ? 0 : 16) + A.rms*24;
  drawingContext.shadowColor = style === 'blueprint' ? 'rgba(180,225,255,0.9)' : 'rgba(255,220,150,0.9)';
  fill(hh, hs, hbb, 95); ellipse(x, y, head + 2);
  drawingContext.shadowBlur = 0;
  pop();
}
